<?php
require_once __DIR__ . '/partials.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$stmt = db()->prepare('SELECT items.*, users.name AS owner_name FROM items JOIN users ON users.id=items.owner_id WHERE items.id=?');
$stmt->bind_param('i', $id); $stmt->execute(); $item = $stmt->get_result()->fetch_assoc();
if (!$item) { http_response_code(404); page_header('Item not found'); echo '<section class="empty"><h1>Item not found</h1><a href="index.php">Back to items</a></section>'; page_footer(); exit; }
page_header($item['title']);
?>
<p class="breadcrumb"><a href="index.php">Explore</a> / <?= e($item['category']) ?></p>
<div class="detail-layout"><?php if ($item['image_filename']): ?><img class="detail-art item-photo" src="uploads/<?= e($item['image_filename']) ?>" alt="<?= e($item['title']) ?>"><?php else: ?><div class="detail-art item-icon <?= strtolower(e($item['category'])) ?>" aria-hidden="true"><?= ['Books'=>'▤','Electronics'=>'⌁','Lab'=>'⚗','Other'=>'✳'][$item['category']] ?></div><?php endif; ?><section class="detail-content"><span class="tag"><?= e($item['category']) ?></span><h1><?= e($item['title']) ?></h1><p class="lead"><?= nl2br(e($item['description'])) ?></p><div class="facts"><div><span>Price</span><strong><?php if ($item['pricing_mode']==='hourly'): ?>₹<?= number_format((float)$item['hourly_rate'],2) ?> per hour<?php else: ?><?= (float)$item['borrowing_fee'] > 0 ? '₹'.number_format((float)$item['borrowing_fee'],2).' flat' : 'Free' ?><?php endif; ?></strong></div><div><span>Minimum time</span><strong><?= (int)$item['minimum_hours'] ?> hour<?= (int)$item['minimum_hours']===1 ? '' : 's' ?></strong></div><div><span>Pickup spot</span><strong><?= e($item['pickup_location']) ?></strong></div><div><span>Shared by</span><strong><?= e($item['owner_name']) ?></strong></div><div><span>Status</span><strong><?= $item['status'] === 'available' ? 'Available' : 'Currently borrowed' ?></strong></div></div>
<?php if (!user_id()): ?><p><a class="button" href="account.php">Log in to request</a></p>
<?php elseif (user_id() === (int) $item['owner_id']): ?><p class="hint">This is your listing. Manage it from your dashboard.</p>
<?php elseif ($item['status'] === 'available'): ?><form action="action.php" method="post" class="request-form" data-validate data-cost-preview data-mode="<?= e($item['pricing_mode']) ?>" data-flat="<?= e($item['borrowing_fee']) ?>" data-rate="<?= e($item['hourly_rate']) ?>" data-minimum="<?= (int)$item['minimum_hours'] ?>"><h2>Ask to borrow</h2><p>Tell the owner when you need it and how you will return it.</p><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="item_id" value="<?= (int) $item['id'] ?>"><div class="field"><label for="start_at">Pickup time (IST)</label><input id="start_at" name="start_at" type="datetime-local" min="<?= date('Y-m-d\TH:i') ?>" required></div><div class="field"><label for="end_at">Return time (IST)</label><input id="end_at" name="end_at" type="datetime-local" required></div><div class="cost-preview" aria-live="polite"><span data-duration>Choose pickup and return times to see the total.</span><strong data-total></strong></div><div class="field"><label for="message">Message to owner</label><textarea id="message" name="message" required maxlength="250" rows="3" placeholder="Hi! Could I borrow this for my lab on Friday?"></textarea></div><?php if ((float)($item['pricing_mode']==='hourly' ? $item['hourly_rate'] : $item['borrowing_fee']) > 0): ?><div class="field"><label for="payment_method">Pay owner at pickup using</label><select id="payment_method" name="payment_method" required><option value="">Choose a method</option><option value="cash">Cash</option><option value="upi">UPI</option></select><small>Borrow Box records the agreement; it does not transfer money.</small></div><?php endif; ?><button class="button" name="action" value="request">Send request</button></form>
<?php else: ?><p class="hint">This item is currently borrowed. Check back later.</p><?php endif; ?></section></div>
<?php page_footer(); ?>
